      SUBROUTINE RCOUT2CC     PRINTS SECOND-ORDER TRANSFER MATRIXCC ----------------------------------------------------------------------      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'TS.CIN'CC     LOCAL VARIABLESC      INTEGER         J, JK, K, K1, K1K2, K2, L1, L1L2, L2, N      INTEGER         ISH1(9), ISH2(9), ISV1(6), ISV2(6)      REAL            OUTPUT(10)      DATA ISH1 /1,1,2,3,3,4,1,2,6/      DATA ISH2 /1,2,2,3,4,4,6,6,6/      DATA ISV1 /1,2,1,2,3,4/      DATA ISV2 /3,3,4,4,6,6/C ---------------------------------------------------------------------CC     PRINT SECOND ORDER TRANSFER MATRIXC      IF (TERSE) GO TO 250      WRITE (NOUT,1011) 1011 FORMAT (1H0,8X,'*2ND ORDER TRANSFORM*')      DO 210 N = 1, 5      JK = 0      DO 209 J = 1, 6      DO 208 K = 1, J      JK = JK + 1      OUTPUT(K) = TS(N,JK)*UBEAM(J)*UBEAM(K)/UBEAM(N)  208 CONTINUE      WRITE (NOUT,1009) (N, K, J, OUTPUT(K), K = 1, J) 1009 FORMAT (8X,6(I4,I2,I1,1PE11.3))  209 CONTINUE      WRITE (NOUT,1010) 1010 FORMAT (1H )  210 CONTINUE      GO TO 400C  250 DO 280 J = 1, 9      K1 = ISH1(J)      K2 = ISH2(J)      K1K2 = K2*(K2-1)/2 + K1      OUTPUT(1) = TS(1,K1K2)*UBEAM(K1)*UBEAM(K2)/UBEAM(1)      OUTPUT(2) = TS(2,K1K2)*UBEAM(K1)*UBEAM(K2)/UBEAM(2)      IF (J .GT. 6) GO TO 260      L1 = ISV1(J)      L2 = ISV2(J)      L1L2 = L2*(L2-1)/2 + L1      OUTPUT(3) = TS(3,L1L2)*UBEAM(L1)*UBEAM(L2)/UBEAM(3)      OUTPUT(4) = TS(4,L1L2)*UBEAM(L1)*UBEAM(L2)/UBEAM(4)      WRITE (NOUT,1005) K1, K2, OUTPUT(1), K1, K2, OUTPUT(2),     1                  L1, L2, OUTPUT(3), L1, L2, OUTPUT(4)      IF (NORD3 .EQ. 1) RETURN 1005 FORMAT (1H ,37X,1H1,I2,I1,1PE11.3,3X,1H2,I2,I1,1PE11.3,     1        3X,1H3,I2,I1,1PE11.3,3X,1H4,I2,I1,1PE11.3)      GO TO 280  260 WRITE (NOUT,1006) K1, K2, OUTPUT(1), K1, K2, OUTPUT(2) 1006 FORMAT (1H ,37X,1H1,I2,I1,1PE11.3,3X,1H2,I2,I1,1PE11.3)  280 CONTINUEC  400 RETURN      END